{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": [
    "C01", "C02", "C03", "C04", "C06", "C07", "C08", "C09", "C10",
    "C11", "C12", "C13", "C14", "C15", "C16", "C17", "C18", "C19",
    "C20", "C21", "C22", "C24", "C36", "C40", "C45", "C46"
  ],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": [
    "C24", "C36", "C40", "C45", "C46", "C01", "C10"
  ],
  "claims": [
    {
      "claim": "The query is a 4-amino-5-chloro-2-alkoxybenzamide closely related to mosapride; mosapride oral exposure (C24) and rapid, near-complete dissolution/solubility records (C36, C40, C45, C46) support an adequate intestinal absorption component, and no L4 record provides negative absorption evidence.",
      "card_ids": ["C24", "C36", "C40", "C45", "C46"]
    },
    {
      "claim": "All quantified gold-context oral bioavailability values are at or above 35% (e.g., safinamide ~95%, GSK1322322 77%, encainide 52-78%, vernakalant 58-71%, ketanserin 49-60%, haloperidol 35%, ebastine ~40%, ONO-4641 0.71), and none affirmatively supports F < 20%.",
      "card_ids": ["C01", "C02", "C03", "C04", "C06", "C07", "C08", "C09", "C10", "C11", "C12", "C13", "C14", "C15", "C16", "C17", "C21", "C22"]
    },
    {
      "claim": "The only qualitative 'low' bioavailability card (C23) is unquantified, conflicts with C02 (~40%) and C18 ('highly bioavailable') for ebastine, and is not threshold-relevant to the query.",
      "card_ids": ["C02", "C18", "C23"]
    },
    {
      "claim": "L4 absorption/permeability records for other molecules (flecainide C37/C41, midodrine C43) are consistent with good oral absorption but are less transferable; they do not change the direction of evidence.",
      "card_ids": ["C37", "C41", "C43"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C36", "C40", "C45", "C46"]
    }
  ],
  "evidence_gaps": [
    "No direct same-molecule absolute oral bioavailability measurement for the query.",
    "Mosapride AUC (C24) lacks an IV comparator, so it cannot quantify F.",
    "L4 solubility/dissolution records are for mosapride, not the query; the query's piperidine linker and propoxy-4-fluorophenyl substituent may alter permeability and first-pass handling.",
    "No query-specific permeability, efflux, or intestinal metabolism data.",
    "Gold-context transfer is indirect and structurally diverse."
  ],
  "decision_summary": "L4 adds mosapride solubility/dissolution evidence supporting the absorption component; combined with close structural analogy and absence of affirmative low-F evidence, the high prediction is retained and modestly strengthened, with moderate confidence."
}

